// Security → Flow tab (coordination × profile), AS GRAPH SOURCE (#3646, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the security lib surface via the security graph-platform,
// and the sibling tab bodies as @/components/* graph records). Behaviour runs here — no forked render path.
// Security — Flow tab (#1643 split from SecurityWorkspace).
//
// The fleet's live work-flow: which sessions are parked on a dependency (#199) — each
// cross-referenced with the permission profile the session runs under. Coord state is
// rebuilt from the app-wide $BSC_COORD_LOG via read_coord_log + ingestCoordLog, so it
// needs no store wiring. Summary + status colors are pure (./lib/flowModel).
// Preview note: the coordination-log poll (`usePoll` + `readCoordState` + `actuateWake`) and the
// flowModel/coordination libs are app-internal (unresolvable in this sandbox) — inlined locally below
// with static sample coordination data so this tab previews standalone.

import { useCallback, useState } from "react";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { Chip } from "@/shared/ui/data/Chip";
import { StatTile } from "@/shared/ui/data/StatTile";
import { SectionHeader } from "@/shared/ui/layout/SectionHeader";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Spacer } from "@/shared/ui/layout/Spacer";

interface AgentProfile { id: string; name: string; color: string }
interface DepRef { ref: string; status: "pending" | "blocked" | "ready" }
interface BlockedView { session: string; deadlocked: boolean; stalled: boolean; checkpoint?: string; deps: DepRef[] }
interface Waiter { session: string; checkpoint?: string }

function depColor(status: DepRef["status"]): string {
  return status === "ready" ? "var(--success)" : status === "blocked" ? "var(--danger)" : "var(--accent)";
}
function flowSummary(views: BlockedView[], ready: Waiter[]): { stalled: number; deadlocked: number; idle: boolean } {
  const deadlocked = views.filter((v) => v.deadlocked).length;
  const stalled = views.filter((v) => v.stalled && !v.deadlocked).length;
  return { stalled, deadlocked, idle: views.length === 0 && ready.length === 0 };
}
function wakePromptFor(w: Waiter): string { return `Resuming after ${w.checkpoint ?? "the dependency landed"} — pick up where you left off.`; }

const SAMPLE_PROFILES: Record<string, AgentProfile> = {
  "worker-1": { id: "pf_sandbox", name: "Sandbox", color: "oklch(0.78 0.14 70)" },
  "worker-2": { id: "pf_reviewer", name: "Reviewer", color: "oklch(0.68 0.18 25)" },
  "worker-3": { id: "pf_sandbox", name: "Sandbox", color: "oklch(0.78 0.14 70)" },
  "worker-5": { id: "pf_reviewer", name: "Reviewer", color: "oklch(0.68 0.18 25)" },
};
const SAMPLE_READY: Waiter[] = [{ session: "worker-3", checkpoint: "build-passed" }];
const SAMPLE_BLOCKED: BlockedView[] = [
  { session: "worker-2", deadlocked: false, stalled: true, deps: [{ ref: "worker-1:merge", status: "pending" }] },
  { session: "worker-5", deadlocked: true, stalled: false, checkpoint: "audit-clean", deps: [{ ref: "worker-6:release", status: "blocked" }, { ref: "worker-2:merge", status: "pending" }] },
];

/** A compact "session @ profile" chip — the Agents-screen cross-reference. */
function SessionTag({ session, profile }: { session: string; profile?: AgentProfile }) {
  return (
    <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
      <Text as="h3" mono weight={600} size={13} style={{ margin: 0 }}>{session}</Text>
      {profile && (
        <Box as="span" className="hint mono" style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 10 }}>
          <Box as="span" bg={profile.color} radius={2} style={{ width: 8, height: 8, display: "inline-block" }} />
          {profile.name}
        </Box>
      )}
    </Box>
  );
}

export interface FlowTabProps {
  wakePane?: (paneId: string, prompt: string) => boolean;
  profileFor?: (session: string) => AgentProfile | undefined;
}

export function FlowTab({ wakePane = () => true, profileFor = (s) => SAMPLE_PROFILES[s] }: FlowTabProps) {
  const [views] = useState<BlockedView[]>(SAMPLE_BLOCKED);
  const [ready] = useState<Waiter[]>(SAMPLE_READY);
  const [err] = useState<string | null>(null);
  const [waking, setWaking] = useState<Set<string>>(new Set());

  const handleWake = useCallback(async (wtr: Waiter) => {
    setWaking((cur) => new Set(cur).add(wtr.session));
    await new Promise((r) => setTimeout(r, 400));
    wakePane(wtr.session, wakePromptFor(wtr));
    setWaking((cur) => { const n = new Set(cur); n.delete(wtr.session); return n; });
  }, [wakePane]);

  const { stalled, deadlocked, idle } = flowSummary(views, ready);

  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="ready" v={ready.length} tone="success" sub="deps landed — wake" />
        <StatTile k="blocked" v={views.length} tone="accent" sub="parked on a dep" />
        <StatTile k="stalled / deadlocked" v={stalled + deadlocked} tone="danger" sub={<>{deadlocked} cyclic · escalate</>} />
      </Box>

      {deadlocked > 0 && (
        <Card style={{ margin: "0 0 14px", borderColor: "var(--danger)" }}>
          <Row gap={8} wrap className="mono" style={{ color: "var(--danger)", fontSize: 12 }}>
            <Box as="span">⚠ deadlock</Box>
            <Text as="span" className="hint" tone="muted">
              {deadlocked} session{deadlocked === 1 ? "" : "s"} sit in a wait-for cycle — no producer can move. Escalate to the director / break the cycle (#199).
            </Text>
          </Row>
        </Card>
      )}

      {err && <Text as="div" mono size={11} tone="danger" style={{ marginBottom: 10 }}>{err}</Text>}

      {idle && !err && (
        <Text as="div" className="hint" mono size={11.5} style={{ padding: "8px 2px" }}>
          The fleet is flowing. Sessions appear here when a worker pauses for you (<code>bsc-wait</code>)
          or asks the director a question (<code>bsc-ask</code>).
        </Text>
      )}

      {ready.length > 0 && (
        <>
          <SectionHeader title="Ready" hint="deps landed" />
          <Box style={{ marginBottom: 14 }}>
            {ready.map((wtr) => (
              <Card key={wtr.session} style={{ marginBottom: 10, borderColor: "var(--success)" }}>
                <Row gap={10} wrap align="center">
                  <SessionTag session={wtr.session} profile={profileFor(wtr.session)} />
                  <Chip tone="success" style={{ fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />ready</Chip>
                  <Spacer />
                  {wtr.checkpoint && <Text as="span" className="hint" mono size={10}>↺ {wtr.checkpoint}</Text>}
                  <Button
                    variant="primary"
                    style={{ height: 24, padding: "0 12px", fontSize: 11 }}
                    disabled={waking.has(wtr.session)}
                    onClick={() => handleWake(wtr)}
                  >
                    {waking.has(wtr.session) ? "waking…" : "Wake"}
                  </Button>
                </Row>
              </Card>
            ))}
          </Box>
        </>
      )}

      {views.length > 0 && (
        <>
          <SectionHeader title="Blocked" hint="parked on a dependency" />
          {views.map((v) => (
            <Card key={v.session} style={{ marginBottom: 10, borderColor: v.deadlocked || v.stalled ? "var(--danger)" : undefined }}>
              <Row gap={10} wrap style={{ marginBottom: 8 }} align="center">
                <SessionTag session={v.session} profile={profileFor(v.session)} />
                {v.deadlocked
                  ? <Chip style={{ color: "var(--danger)", fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />deadlocked</Chip>
                  : v.stalled
                    ? <Chip style={{ color: "var(--danger)", fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />stalled</Chip>
                    : <Chip style={{ fontSize: 9.5 }}>waiting</Chip>}
                <Spacer />
                {v.checkpoint && <Text as="span" className="hint" mono size={10}>↺ {v.checkpoint}</Text>}
              </Row>
              <Row gap={6} wrap align="stretch">
                {v.deps.map((d) => (
                  <Box as="span" key={d.ref} className="mono" pad={[3, 8]} border="soft" radius={5} style={{
                    fontSize: 11, color: depColor(d.status),
                  }}>
                    {d.ref} · {d.status}
                  </Box>
                ))}
              </Row>
            </Card>
          ))}
        </>
      )}
    </Box>
  );
}

